query Entity($id: UUID!, $spaceId: UUID, $cursor: Cursor) {
  entity(id: $id) {
    id
    name
    description
    spaceIds
    updatedAt
    types { id name }
    allValuesList: valuesList(first: 1000) { spaceId propertyId }
    allRelationsList: relationsList(first: 1000) { spaceId }
    valuesList(first: 1000, filter: { spaceId: { is: $spaceId } }) { ...EntityValueFields }
    relations(first: 500, after: $cursor, filter: { spaceId: { is: $spaceId } }) {
      pageInfo { hasNextPage endCursor }
      nodes { ...RelationFields }
    }
  }
}
fragment RelationToEntity on Entity {
  id
  name
  types { id }
  valuesList(first: 1000) { spaceId propertyId text }
}
fragment PropertyFragment on PropertyInfo {
  id name dataTypeId dataTypeName renderableTypeId renderableTypeName format isType
}
fragment EntityValueFields on Value {
  spaceId
  property { ...PropertyFragment }
  text integer float point boolean time language unit datetime date decimal schedule
}
fragment RelationFields on Relation {
  id spaceId position verified entityId
  fromEntity { id name }
  toEntity { ...RelationToEntity }
  toSpaceId
  type { id name }
}
